namespace docking.widgets.table;







using ghidra.framework.plugintool;
using ghidra.util;

/**
 * A table model where the columns are enumerated, and the rows are wrappers on the objects being
 * displayed
 * 
 * @param <C> the type of columns
 * @param <K> the type of (immutable) keys for uniquely identifying an object
 * @param <R> the type of rows
 * @param <T> the type of objects being wrapped
 */
public class RowWrappedEnumeratedColumnTableModel<C, K, R, T> : DefaultEnumeratedColumnTableModel<C, R> where C : Enum<C> , EnumeratedTableColumn<C, R> {
	private Function<T, K> keyFunc;
	private Function<T, R> wrapper;
	private Function<R, T> getter;
	private Map<K, R> map = new();

	public RowWrappedEnumeratedColumnTableModel(PluginTool tool, string name, Class<C> colType,
			Function<T, K> keyFunc, Function<T, R> wrapper, Function<R, T> getter) : base(tool, name, colType)
    {
		this.keyFunc = keyFunc;
		this.wrapper = wrapper;
		this.getter = getter;
	}

	protected R addRowFor(T t) {
		R row = wrapper.apply(t);
		R exists = map.put(keyFunc.apply(t), row);
		if (exists != null) {
			Msg.warn(this, "Replaced existing row! row=" + exists);
		}
		return row;
	}

	protected R delRowFor(T t) {
		return delKey(keyFunc.apply(t));
	}

	protected R delKey(K k) {
		return map.remove(k);
	}

	protected List<R> addRowsFor(Stream<T> s) {
		return s.map(this.addRowFor).collect(Collectors.toList());
	}

	protected List<R> addRowsFor(Collection<T> c) {
		return addRowsFor(c.stream());
	}

	public R getRow(T t) {
		return map.get(keyFunc.apply(t));
	}

	protected List<R> getRows(Stream<T> s) {
		return s.map(this.getRow).filter(r => r != null).collect(Collectors.toList());
	}

	protected List<R> getRows(Collection<T> c) {
		return getRows(c.stream());
	}

	public void addItem(T t) {
		if (map.containsKey(keyFunc.apply(t))) {
			return;
		}
		add(addRowFor(t));
	}

	public void addAllItems(Collection<T> c) {
		Stream<T> s = c.stream().filter(t => {
			K k = keyFunc.apply(t);
			if (map.containsKey(k)) {
				return false;
			}
			return true;
		});
		addAll(addRowsFor(s));
	}

	public void updateItem(T t) {
		R row = getRow(t);
		if (row == null) {
			return;
		}
		notifyUpdated(row);
	}

	public void updateAllItems(Collection<T> c) {
		notifyUpdatedWith(getRows(c).contains);
	}

	public void deleteItem(T t) {
		R row = delRowFor(t);
		if (row == null) {
			return;
		}
		delete(row);
	}

	public R deleteKey(K k) {
		R r = delKey(k);
		if (r == null) {
			return null;
		}
		delete(r);
		return r;
	}

	public void deleteItemsWith(Predicate<T> predicate) {
		List<R> deleted = deleteWith(r => predicate.test(getter.apply(r)));
		map.values().removeAll(deleted);
	}

	public void deleteAllItems(Collection<T> c) {
		deleteWith(getRows(c).contains);
		map.keySet().removeAll(c.stream().map(keyFunc).collect(Collectors.toList()));
	}

	public Map<K, R> getMap() {
		return Map.copyOf(map);
	}

	/* @Override */
	public void clear() {
		map.clear();
		base.clear();
	}
}
